import {esc,statusChip} from './status-chip.js';
export function productCard(p,decision,flags=[]){return `<button class="product-row" data-open-product="${esc(p.shopify_product_id)}"><span class="thumb">${p.image_urls_current?.[0]?`<img src="${esc(p.image_urls_current[0])}" alt="">`:''}</span><span class="grow"><strong>${esc(p.title_current)}</strong><small>${esc(p.handle_current)}</small><span>${(p.collections_current||[]).map(x=>statusChip(x)).join(' ')}</span></span><span class="right">${decision?.review_state==='reviewed'?statusChip('REVIEWED','good'):flags.length?statusChip(`${flags.length} FLAGS`,'warn'):statusChip('UNREVIEWED')}</span></button>`}
